-- Title: IAM activate_tenant default store scope
-- Kind: patch
-- Intent: iam_activate_tenant_default_store_scope
-- Context: Ensure tenant store + owner default scope when tenant goes active
-- Touches: iam.activate_tenant
-- Safety: idempotent ; low
-- Depends on: 20260811016_iam_tenant_readiness_activate.sql, 001_iam_ensure_default_store_scope_helpers.sql
-- Promoted from _drafts/007_iam_patch_activate_tenant_default_store_scope.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.activate_tenant(
  p_tenant_id uuid,
  p_expected_version int,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_tenant iam.tenants;
  v_existing iam.tenant_activation_operations;
  v_readiness jsonb;
  v_blockers jsonb;
  v_payload_hash text := md5(p_expected_version::text);
  v_owner_user_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;

  if not iam.has_permission(p_tenant_id, 'tenant.activate') then
    raise exception 'PERMISSION_DENIED';
  end if;

  select * into v_existing
  from iam.tenant_activation_operations o
  where o.tenant_id = p_tenant_id
    and o.idempotency_key = p_idempotency_key;

  if found then
    if v_existing.payload_hash <> v_payload_hash then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.result;
  end if;

  select * into v_tenant from iam.tenants t where t.id = p_tenant_id for update;
  if not found then
    raise exception 'RESOURCE_NOT_FOUND';
  end if;

  perform 1
  from iam.memberships m
  where m.tenant_id = p_tenant_id
    and (m.is_owner is true or m.role in ('owner', 'store_owner'))
    and m.status = 'active'
  for update;

  if v_tenant.status <> 'provisioning' then
    raise exception 'TENANT_STATE_INVALID';
  end if;

  if v_tenant.version <> p_expected_version then
    raise exception 'STATE_CHANGED';
  end if;

  v_readiness := iam.get_tenant_readiness(p_tenant_id);
  v_blockers := v_readiness -> 'blockers';
  if jsonb_array_length(v_blockers) > 0 then
    raise exception 'READINESS_BLOCKED';
  end if;

  update iam.tenants
  set
    status = 'active',
    activated_at = now(),
    status_changed_at = now(),
    version = v_tenant.version + 1,
    updated_at = now()
  where id = p_tenant_id
  returning * into v_tenant;

  perform iam._ensure_tenant_default_store(p_tenant_id);

  select m.user_id
  into v_owner_user_id
  from iam.memberships m
  where m.tenant_id = p_tenant_id
    and (m.is_owner is true or m.role in ('owner', 'store_owner'))
    and m.status = 'active'
  order by m.created_at
  limit 1;

  if v_owner_user_id is not null then
    perform iam._ensure_membership_default_store_scope(p_tenant_id, v_owner_user_id);
  end if;

  v_result := jsonb_build_object(
    'tenant_id', v_tenant.id,
    'status', v_tenant.status,
    'activated_at', v_tenant.activated_at,
    'version', v_tenant.version
  );

  insert into iam.tenant_activation_operations (
    tenant_id,
    idempotency_key,
    payload_hash,
    result
  )
  values (
    p_tenant_id,
    p_idempotency_key,
    v_payload_hash,
    v_result
  );

  perform iam.append_audit_log(
    p_scope => 'tenant',
    p_tenant_id => p_tenant_id,
    p_actor_user_id => auth.uid(),
    p_event_code => 'iam.tenant.activated',
    p_subject_type => 'tenant',
    p_subject_id => v_tenant.id::text,
    p_result => 'success',
    p_source => 'iam',
    p_tracking_id => p_idempotency_key,
    p_before => jsonb_build_object('status', 'provisioning', 'version', p_expected_version),
    p_after => jsonb_build_object('status', v_tenant.status, 'version', v_tenant.version)
  );

  perform iam.enqueue_outbox_message(
    p_tenant_id,
    'iam.tenant.activated',
    jsonb_build_object(
      'tenant_id', v_tenant.id,
      'version', v_tenant.version,
      'activated_at', v_tenant.activated_at
    )
  );

  return v_result;
end;
$$;

revoke all on function iam.activate_tenant(uuid, int, text) from public, anon;
grant execute on function iam.activate_tenant(uuid, int, text) to authenticated;
